using System;
using System.Collections.Generic;
using System.Collections.Immutable;
using System.Globalization;
using System.Linq;
using System.Text;
using System.Threading;

using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Text;

namespace AspectGenerator
{
	[Generator(LanguageNames.CSharp)]
	public class AspectSourceGenerator : IIncrementalGenerator
	{
		#region API

		static string GenerateAspectGeneratorOptionsApiText()
		{
			return
				$$"""
			// <auto-generated/>
			#pragma warning disable
			#nullable enable

			using System;

			namespace AspectGenerator
			{
				/// <summary>
				/// Specifies how AspectGenerator reports optional diagnostics.
				/// </summary>
				/// <remarks>
				/// Values except <see cref="Off"/> map directly to Microsoft.CodeAnalysis.DiagnosticSeverity.
				/// </remarks>
				enum AspectDiagnosticSeverity
				{
					/// <summary>
					/// Do not report optional diagnostics.
					/// </summary>
					Off = -1,
					/// <summary>
					/// Something that is an issue, as determined by some authority, but is not surfaced through normal means.
					/// </summary>
					Hidden = 0,
					/// <summary>
					/// Information that does not indicate a problem.
					/// </summary>
					Info = 1,
					/// <summary>
					/// Something suspicious but allowed.
					/// </summary>
					Warning = 2,
					/// <summary>
					/// Something not allowed by the rules of the language or other authority.
					/// </summary>
					Error = 3,
				}

				/// <summary>
				/// Configures AspectGenerator for the current assembly.
				/// </summary>
				[AttributeUsage(AttributeTargets.Assembly, Inherited = false, AllowMultiple = false)]
				sealed class AspectGeneratorOptionsAttribute : Attribute
				{
					/// <summary>
					/// Gets or sets whether AspectGenerator emits the shared generated API types for this assembly.
					/// </summary>
					/// <remarks>
					/// Keep this enabled for single-project usage. Set it to <c>false</c> when the API is supplied by an aspect library referenced by this project.
					/// </remarks>
					public bool    {{AspectOptionName.GenerateApi}}           { get; set; } = true;
					/// <summary>
					/// Gets or sets whether generated API types are emitted as public types.
					/// </summary>
					/// <remarks>
					/// Use this for aspect-library projects that expose aspect definitions and generated API types to other projects.
					/// </remarks>
					public bool    {{AspectOptionName.PublicApi}}             { get; set; }
					/// <summary>
					/// Gets or sets whether generated interceptor methods are marked with <see cref="System.Diagnostics.DebuggerStepThroughAttribute"/>.
					/// </summary>
					public bool    {{AspectOptionName.DebuggerStepThrough}}   { get; set; }
					/// <summary>
					/// Gets or sets the namespace used for generated interceptor types.
					/// </summary>
					/// <remarks>
					/// The package normally appends this namespace to the project <c>InterceptorsNamespaces</c> MSBuild property for direct package consumers.
					/// Custom build setups must ensure this namespace is listed so Roslyn can use the generated interceptors.
					/// </remarks>
					public string? {{AspectOptionName.InterceptorsNamespace}} { get; set; }
					/// <summary>
					/// Gets or sets how AspectGenerator reports optional diagnostics such as intercepted-call markers.
					/// </summary>
					/// <remarks>
					/// Set to <see cref="AspectGenerator.AspectDiagnosticSeverity.Off"/> to disable optional diagnostics.
					/// </remarks>
					public AspectDiagnosticSeverity {{AspectOptionName.AspectDiagnosticSeverity}} { get; set; } = AspectDiagnosticSeverity.Info;
				}
			}

			""";
		}

		static string GenerateAspectApiText(bool publicApi)
		{
			var visibility = publicApi ? "public " : "";

			return
				$$"""
				// <auto-generated/>
				#pragma warning disable
				#nullable enable

				using System;

				namespace AspectGenerator
				{
				/// <summary>
				/// <para>Defines an aspect.</para>
				/// <para>Create a new attribute decorated with this attribute to define an aspect.</para>
				/// </summary>
				[AttributeUsage(AttributeTargets.Class, Inherited = false, AllowMultiple = false)]
				{{visibility}}sealed class AspectAttribute : Attribute
				{
					/// <summary>
					/// Gets or sets the static hook method name invoked when the aspect invocation state is initialized.
					/// </summary>
					public string?   OnInit            { get; set; }
					/// <summary>
					/// Gets or sets the static hook method name invoked before the target method inside a generated <c>using</c> scope.
					/// </summary>
					/// <remarks>
					/// The returned disposable value is disposed after the intercepted call completes.
					/// </remarks>
					public string?   OnUsing           { get; set; }
					/// <summary>
					/// Gets or sets the static async hook method name invoked before an async target method inside a generated async disposal scope.
					/// </summary>
					public string?   OnUsingAsync      { get; set; }
					/// <summary>
					/// Gets or sets the static hook method name invoked before the target method is called.
					/// </summary>
					public string?   OnBeforeCall      { get; set; }
					/// <summary>
					/// Gets or sets the static async hook method name invoked before a supported async target method is awaited.
					/// </summary>
					public string?   OnBeforeCallAsync { get; set; }
					/// <summary>
					/// Gets or sets the static hook method name that replaces the target method call.
					/// </summary>
					/// <remarks>
					/// The hook signature must match the intercepted method signature and return type.
					/// </remarks>
					public string?   OnCall            { get; set; }
					/// <summary>
					/// Gets or sets the static hook method name invoked after the target method returns successfully.
					/// </summary>
					public string?   OnAfterCall       { get; set; }
					/// <summary>
					/// Gets or sets the static async hook method name invoked after a supported async target method completes successfully.
					/// </summary>
					public string?   OnAfterCallAsync  { get; set; }
					/// <summary>
					/// Gets or sets the static hook method name invoked when the target method throws.
					/// </summary>
					/// <remarks>
					/// Set <see cref="InterceptInfo.InterceptResult"/> or <c>InterceptData&lt;T&gt;.InterceptResult</c> to control whether the exception is rethrown or ignored.
					/// </remarks>
					public string?   OnCatch           { get; set; }
					/// <summary>
					/// Gets or sets the static async hook method name invoked when a supported async target method throws.
					/// </summary>
					public string?   OnCatchAsync      { get; set; }
					/// <summary>
					/// Gets or sets the static hook method name invoked in the generated <c>finally</c> block.
					/// </summary>
					public string?   OnFinally         { get; set; }
					/// <summary>
					/// Gets or sets the static async hook method name invoked in the generated async cleanup path.
					/// </summary>
					public string?   OnFinallyAsync    { get; set; }
					/// <summary>
					/// Gets or sets whether hook data includes the current lifecycle stage.
					/// </summary>
					public bool      UseInterceptType  { get; set; }
					/// <summary>
					/// Gets or sets whether hook data includes the intercepted method arguments.
					/// </summary>
					/// <remarks>
					/// When enabled, generated code populates <see cref="InterceptInfo.MethodArguments"/> or <c>InterceptData&lt;T&gt;.MethodArguments</c>.
					/// </remarks>
					public bool      PassArguments     { get; set; }
					/// <summary>
					/// Gets or sets whether hooks use the mutable <c>ref InterceptData&lt;T&gt;</c> carrier instead of <c>InterceptInfo&lt;T&gt;</c>.
					/// </summary>
					public bool      UseInterceptData  { get; set; }
					/// <summary>
					/// Gets or sets how generated interceptors create and reuse applied aspect attribute instances.
					/// </summary>
					public AspectInstanceLifetime Lifetime { get; set; } = AspectInstanceLifetime.Auto;
					/// <summary>
					/// Gets or sets default target filter rules supplied by the aspect author.
					/// </summary>
					/// <remarks>
					/// These rules are prepended to the <c>TargetFilter</c> supplied when the aspect is applied. The resulting effective filter is evaluated using normal TargetFilter rule ordering.
					/// TargetFilter is compile-time selection metadata and is not copied to the runtime aspect instance.
					/// </remarks>
					public string? DefaultTargetFilter { get; set; }
				}

				/// <summary>
				/// Controls generated aspect attribute instance lifetime.
				/// </summary>
				{{visibility}}enum AspectInstanceLifetime
				{
					/// <summary>
					/// Let AspectGenerator choose the lifetime from the hook contract.
					/// </summary>
					Auto,
					/// <summary>
					/// Reuse one lazily-created aspect attribute instance per generated interceptor.
					/// </summary>
					/// <remarks>
					/// The instance is shared across threads; hooks that mutate it must be thread-safe.
					/// An exception during construction surfaces as a <see cref="TypeInitializationException"/>.
					/// </remarks>
					Static,
					/// <summary>
					/// Create a new aspect attribute instance for each intercepted call.
					/// </summary>
					Instance
				}

				/// <summary>
				/// Identifies the lifecycle stage currently being processed by a hook.
				/// </summary>
				{{visibility}}enum InterceptType
				{
					/// <summary>
					/// Aspect invocation state is being initialized.
					/// </summary>
					OnInit,
					/// <summary>
					/// The generated using-scope hook is being entered.
					/// </summary>
					OnUsing,
					/// <summary>
					/// The target method is about to be called.
					/// </summary>
					OnBeforeCall,
					/// <summary>
					/// The target method returned successfully.
					/// </summary>
					OnAfterCall,
					/// <summary>
					/// The target method threw an exception.
					/// </summary>
					OnCatch,
					/// <summary>
					/// The generated cleanup path is running.
					/// </summary>
					OnFinally
				}

				/// <summary>
				/// Controls how generated interceptor code continues after a hook is executed.
				/// </summary>
				{{visibility}}enum InterceptResult
				{
					/// <summary>
					/// Continue normal generated interceptor flow.
					/// </summary>
					Continue,
					/// <summary>
					/// Return the current value from the interceptor.
					/// </summary>
					Return,
					/// <summary>
					/// Alias for <see cref="Continue"/> used by exception hooks to rethrow the current exception.
					/// </summary>
					ReThrow     = Continue,
					/// <summary>
					/// Alias for <see cref="Return"/> used by exception hooks to ignore the current exception.
					/// </summary>
					IgnoreThrow = Return
				}

				/// <summary>
				/// Represents a void return value in generic hook data.
				/// </summary>
				{{visibility}}struct Void
				{
				}

				/// <summary>
				/// Provides hook data for an intercepted method.
				/// </summary>
				{{visibility}}partial class InterceptInfo
				{
					/// <summary>
					/// Gets or sets user-defined state shared between hooks in the same interception chain.
					/// </summary>
					public object?         Tag;
					/// <summary>
					/// Gets or sets the current lifecycle stage.
					/// </summary>
					public InterceptType   InterceptType;
					/// <summary>
					/// Gets or sets the requested continuation behavior for generated interceptor code.
					/// </summary>
					public InterceptResult InterceptResult;
					/// <summary>
					/// Gets or sets the current exception for catch and finally hooks.
					/// </summary>
					public Exception?      Exception;
					/// <summary>
					/// Gets or sets hook data produced by the previous aspect in the same interception chain.
					/// </summary>
					public InterceptInfo?  PreviousInfo;
					/// <summary>
					/// Gets or sets intercepted method arguments when argument capture is enabled.
					/// </summary>
					public object?[]?      MethodArguments;
					/// <summary>
					/// Gets or sets the applied aspect attribute instance.
					/// </summary>
					public Attribute?      Aspect;
					/// <summary>
					/// Gets or sets reflection metadata for the intercepted target method.
					/// </summary>
					public System.Reflection.MemberInfo MemberInfo;
				}

				/// <summary>
				/// Provides hook data for an intercepted method with a return value.
				/// </summary>
				/// <typeparam name="T">The intercepted method return value type.</typeparam>
				{{visibility}}partial class InterceptInfo<T> : InterceptInfo
				{
					/// <summary>
					/// Gets or sets the intercepted method return value.
					/// </summary>
					public T ReturnValue;
				}

				/// <summary>
				/// Provides mutable by-reference hook data for an intercepted method.
				/// </summary>
				/// <typeparam name="T">The intercepted method return value type.</typeparam>
				{{visibility}}partial struct InterceptData<T>
				{
					/// <summary>
					/// Gets or sets user-defined state shared between hooks in the same interception chain.
					/// </summary>
					public object?         Tag;
					/// <summary>
					/// Gets or sets the current lifecycle stage.
					/// </summary>
					public InterceptType   InterceptType;
					/// <summary>
					/// Gets or sets the requested continuation behavior for generated interceptor code.
					/// </summary>
					public InterceptResult InterceptResult;
					/// <summary>
					/// Gets or sets the current exception for catch and finally hooks.
					/// </summary>
					public Exception?      Exception;
					/// <summary>
					/// Gets or sets intercepted method arguments when argument capture is enabled.
					/// </summary>
					public object?[]?      MethodArguments;
					/// <summary>
					/// Gets or sets the applied aspect attribute instance.
					/// </summary>
					public Attribute?      Aspect;
					/// <summary>
					/// Gets or sets the intercepted method return value.
					/// </summary>
					public T               ReturnValue;
					/// <summary>
					/// Gets or sets hook data produced by the previous aspect in the same interception chain.
					/// </summary>
					public InterceptInfo<T>? PreviousInfo;
					/// <summary>
					/// Gets or sets reflection metadata for the intercepted target method.
					/// </summary>
					public System.Reflection.MemberInfo MemberInfo;
				}
			}

			""";
		}

		#endregion

		internal record AnalysisResult(
			Compilation                        Compilation,
			GeneratorExecutionOptions          Options,
			ImmutableArray<AnalyzedInvocation> AspectedMethods,
			ImmutableArray<DiagnosticInfo>     Diagnostics,
			GeneratorTraceReport               Trace);

		public void Initialize(IncrementalGeneratorInitializationContext context)
		{
#if DEBUG && TRUE1
			if (!System.Diagnostics.Debugger.IsAttached)
			{
				System.Diagnostics.Debugger.Launch();
			}
#endif

			context.RegisterPostInitializationOutput(static context =>
			{
				context.AddSource("AspectGeneratorOptionsAttribute.g.cs", SourceText.From(GenerateAspectGeneratorOptionsApiText(), Encoding.UTF8));
			});

			var attributes = context.SyntaxProvider
				.CreateSyntaxProvider(
					predicate: static (node, _) => AspectDefinitionRegistry.IsAspectDeclarationCandidate(node),
					transform: static (ctx, _) => (ClassDeclarationSyntax)ctx.Node)
				.Collect();

			var invocations = context.SyntaxProvider
				.CreateSyntaxProvider(
					predicate: static (node, _) => AspectSelectionService.IsCandidateInvocation(node),
					transform: static (ctx, _) => (InvocationExpressionSyntax)ctx.Node)
				.Collect();

			var methodDeclarations = context.SyntaxProvider
				.CreateSyntaxProvider(
					predicate: static (node, _) => node is MethodDeclarationSyntax,
					transform: static (ctx, _) => (MethodDeclarationSyntax)ctx.Node)
				.Collect();

			var appliedAttributes = context.SyntaxProvider
				.CreateSyntaxProvider(
					predicate: static (node, _) => node is AttributeSyntax,
					transform: static (ctx, _) => (AttributeSyntax)ctx.Node)
				.Collect();

			var options = context.AnalyzerConfigOptionsProvider.Select(static (c, _) =>
				AspectOptionsResolver.GetMSBuildOptions(c));

			var analysis = context.CompilationProvider
				.Combine(options)
				.Combine(attributes)
				.Combine(appliedAttributes)
				.Combine(invocations)
				.Combine(methodDeclarations)
				.Select(static (data, ct) => Analyze(data, ct));

			context.RegisterSourceOutput(analysis, ReportDiagnostics);
			context.RegisterImplementationSourceOutput(analysis, EmitInterceptors);
		}

		static AnalysisResult Analyze(
			(((((Compilation Left, Options Right) Left, ImmutableArray<ClassDeclarationSyntax> Right) Left, ImmutableArray<AttributeSyntax> Right) Left, ImmutableArray<InvocationExpressionSyntax> Right) Left, ImmutableArray<MethodDeclarationSyntax> Right) data,
			CancellationToken cancellationToken)
		{
			var compilation         = data.Left.Left.Left.Left.Left;
			var diagnosticSink      = new GeneratorDiagnosticSink();
			var diagnostics         = diagnosticSink.Diagnostics;
			var reportedDiagnostics = new HashSet<string>();
			var options = AspectOptionsResolver.Resolve(compilation, data.Left.Left.Left.Left.Right, diagnosticSink);
			var trace = GeneratorTraceReport.Create(options);
			trace.AddCompilation(compilation, options);
			trace.AddOptions(options);
			var attrs               = data.Left.Left.Left.Right;
			var appliedAttributes   = data.Left.Left.Right;
			var invocations         = data.Left.Right;
			var methodDeclarations  = data.Right;

			trace.SetCounter("Applied aspect attributes", 0);
			trace.SetCounter("Target filters", 0);
			trace.SetCounter("Candidate target methods", 0);
			trace.SetCounter("Target method declarations", 0);
			trace.SetCounter("Target methods after declaration filter", 0);
			trace.SetCounter("Target methods after semantic filter", 0);
			trace.SetCounter("Invocation candidates before prefilter", invocations.Length);
			trace.SetCounter("Invocation candidates after prefilter", 0);
			trace.SetCounter("Symbol resolution attempts", 0);
			trace.SetCounter("Symbol resolution successes", 0);
			trace.SetCounter("Symbol resolution failures", 0);
			trace.SetCounter("Call-site prefilter rejected missing method name", 0);
			trace.SetCounter("Call-site prefilter rejected generic arity", 0);
			trace.SetCounter("Call-site prefilter rejected argument count", 0);
			trace.SetCounter("Call-site prefilter rejected receiver type", 0);
			trace.SetCounter("Applied target filter matches", 0);
			trace.SetCounter("AG0300 markers reported", 0);
			trace.SetCounter("Candidate call syntax nodes", invocations.Length);
			trace.SetCounter("Aspect definitions", attrs.Length);
			trace.SetCounter("Applied aspect attribute candidates", appliedAttributes.Length);

			AspectDefinitionRegistry registry;
			using (trace.TimePhase("Discover aspect definitions"))
				registry = AspectDefinitionRegistry.Create(
					compilation,
					attrs,
					diagnosticSink,
					cancellationToken);

			using (trace.TimePhase("Validate aspect hooks"))
				ValidateAspectHooks(diagnostics, registry.AspectAttributes, reportedDiagnostics);

			var externalAspectDefinitionsPossible = AspectDefinitionRegistry.HasExternalAspectDefinitions(compilation);

			if (options.DesignTimeBuild)
				return AnalyzeDesignTimeBuild(compilation, options, registry, diagnosticSink, trace, appliedAttributes, externalAspectDefinitionsPossible, cancellationToken);

			var appliedAspectCount = CountAppliedAspectAttributes(compilation, registry, appliedAttributes, cancellationToken);
			trace.SetCounter("Applied aspect attributes", appliedAspectCount);

			ImmutableArray<AnalyzedInvocation> aspectedMethods;

			if (registry.AspectAttributes.Count == 0 && !externalAspectDefinitionsPossible)
			{
				trace.AddDecision("Fast path: no AspectAttribute definitions found.");
				trace.AddDecision("scan-call-sites: skipped reason=no-aspect-definitions");
				trace.AddDecision("resolve-call-symbols: skipped reason=no-aspect-definitions");
				trace.SkipPhase("Build target filters");
				trace.SkipPhase("Collect target methods");
				trace.SkipPhase("Scan call sites");
				trace.SkipPhase("Resolve call symbols");
				trace.SkipPhase("Apply target filters");
				aspectedMethods = [];
			}
			else if (appliedAspectCount == 0 && !externalAspectDefinitionsPossible)
			{
				trace.AddDecision("Fast path: no applied aspect attributes found.");
				trace.AddDecision("scan-call-sites: skipped reason=no-applied-aspects");
				trace.AddDecision("resolve-call-symbols: skipped reason=no-applied-aspects");
				trace.SkipPhase("Build target filters");
				trace.SkipPhase("Collect target methods");
				trace.SkipPhase("Scan call sites");
				trace.SkipPhase("Resolve call symbols");
				trace.SkipPhase("Apply target filters");
				aspectedMethods = [];
			}
			else
			{
				AspectSelectionService selection;
				using (trace.TimePhase("Build target filters"))
					selection = new AspectSelectionService(
						compilation,
						options,
						registry,
						diagnosticSink,
						trace);

				trace.AddDecision("target-selection: declaration-first enabled");

				selection.ReportLocalFunctionTargetFilters(appliedAttributes, cancellationToken);

				AspectSelectionPlan selectionPlan;
				using (trace.TimePhase("Collect target methods"))
					selectionPlan = selection.BuildSelectionPlan(methodDeclarations, externalAspectDefinitionsPossible, cancellationToken);

				if (selectionPlan.SelectedTargetMethods.Count == 0 && !selectionPlan.MayTargetExternalMethods && selectionPlan.ExternalTargetMethodNames.Count == 0)
				{
					trace.AddDecision("scan-call-sites: skipped reason=no-selected-target-methods");
					trace.AddDecision("resolve-call-symbols: skipped reason=no-selected-target-methods");
					trace.SkipPhase("Scan call sites");
					trace.SkipPhase("Resolve call symbols");
					trace.SkipPhase("Apply target filters");
					aspectedMethods = [];
				}
				else
				{
					if (selectionPlan.MayTargetExternalMethods)
					{
						trace.AddDecision("scan-call-sites: required reason=external-targets-possible");
						trace.AddDecision("callsite-prefilter: disabled reason=external-targets-possible");
						trace.AddDecision("resolve-call-symbols: required reason=external-targets-possible");
					}
					else if (selectionPlan.SelectedTargetMethods.Count == 0)
					{
						trace.AddDecision("scan-call-sites: required reason=external-target-names");
						trace.AddDecision("callsite-prefilter: enabled kind=method-name-set");
						trace.AddDecision("resolve-call-symbols: required reason=external-target-names");
					}
					else
					{
						trace.AddDecision("scan-call-sites: required reason=selected-target-methods-found");
						trace.AddDecision("callsite-prefilter: enabled kind=method-name-set");
						trace.AddDecision("resolve-call-symbols: required reason=selected-target-methods-found");
					}

					using (trace.TimePhase("Scan call sites"))
					{
					}

					using (trace.TimePhase("Resolve call symbols"))
						aspectedMethods = selection.AnalyzeInvocations(invocations, selectionPlan, cancellationToken);

					foreach (var (reason, count) in selection.GetFilterSelectedSkips())
						diagnostics.Add(
							new DiagnosticInfo(
								AspectDiagnosticID.FilterSelectedCallsNotIntercepted,
								AspectDiagnostics.GetFilterSelectedCallsNotInterceptedMessage(count, reason),
								Location.None,
								DiagnosticSeverity.Info));

					using (trace.TimePhase("Apply target filters"))
					{
					}
				}
			}

			aspectedMethods = [..aspectedMethods.Select(static m => m with { Attributes = InterceptorNamingService.GetOrderedAttributes(m.Attributes) })];

			trace.SetCounter("Intercepted call sites", aspectedMethods.Length);
			trace.SetCounter("Matched target methods", aspectedMethods.Select(static m => m.Method).Distinct(SymbolEqualityComparer.Default).Count());
			trace.SetCounter("Generated interceptor methods", aspectedMethods.GroupBy(static m => m, InterceptorGroupComparer.Instance).Count());

			if (!cancellationToken.IsCancellationRequested)
				using (trace.TimePhase("Validate method hooks"))
				{
					var iteratorIndex = new IteratorOverrideIndex(compilation, trace);
					var dropped = new Dictionary<IMethodSymbol,List<AttributeInfo>>(SymbolEqualityComparer.Default);

					foreach (var m in aspectedMethods.GroupBy(static m => m.Method, SymbolEqualityComparer.Default))
						if (ValidateAspectHooksForMethod(diagnostics, compilation, options.TargetFramework, m.First().Inv, (IMethodSymbol)m.Key!, m.First().Attributes, reportedDiagnostics, iteratorIndex) is { Count: > 0 } failed)
							dropped.Add((IMethodSymbol)m.Key!, failed);

					// An aspect whose hook call would not compile has been reported; it is left out of the interceptor, and a
					// target with no aspect left gets none.
					if (dropped.Count > 0)
						aspectedMethods =
						[
							..aspectedMethods
								.Select(m => dropped.TryGetValue(m.Method, out var failed) ? m with { Attributes = m.Attributes.Where(a => !failed.Contains(a)).ToList() } : m)
								.Where(static m => m.Attributes.Count > 0)
						];
				}

			if (options.EmitInterceptors && aspectedMethods.Length > 0)
			{
				using (trace.TimePhase("Interceptors namespace validation"))
				{
					// Without the package's build props and without a namespace wired up by hand, the interceptors cannot compile:
					// one warning names the cause instead of the less specific AG0004. A project wired by hand is checked as before.
					if (options.PropsImported || IsInterceptorsNamespaceListed(options))
						ReportMissingInterceptorsNamespace(diagnostics, options);
					else
						ReportBuildPropsNotImported(diagnostics);
				}
			}
			else
			{
				trace.AddDecision("Interceptors namespace validation skipped: no generated interceptors.");
				trace.AddDecision("ag0004: skipped reason=no-generated-interceptors");
				trace.SkipPhase("Interceptors namespace validation");
			}

			if (aspectedMethods.Length == 0)
				trace.AddDecision("No intercepted call sites; source generation skipped.");

			trace.SetCounter("Diagnostics reported", diagnostics.Count);

			return new AnalysisResult(compilation, options, aspectedMethods, [..diagnostics], trace);
		}

		/// <summary>
		/// A design-time build (the IDE) emits no interceptors, so it needs neither the applied-aspect count, nor the
		/// selection plan, nor bound call sites, which together cost seconds per edit on a large project. The target filters
		/// are still compiled, from the attributes that carry one, so that their diagnostics stay live in the editor, as do
		/// the hook checks of the aspects declared here and the options checks. The checks that need a selected target
		/// method or a bound call (AG0001, AG0002, AG0003, AG0006, AG0007, AG0103 to AG0107, and AG0101/AG0102 for aspects of
		/// referenced assemblies) are reported by builds only. AG0004 and AG0005 concern the generated interceptors and
		/// were never reported in design-time builds.
		/// </summary>
		static AnalysisResult AnalyzeDesignTimeBuild(
			Compilation                     compilation,
			GeneratorExecutionOptions       options,
			AspectDefinitionRegistry        registry,
			GeneratorDiagnosticSink         diagnosticSink,
			GeneratorTraceReport            trace,
			ImmutableArray<AttributeSyntax> appliedAttributes,
			bool                            externalAspectDefinitionsPossible,
			CancellationToken               cancellationToken)
		{
			trace.AddDecision("design-time build: target selection and call binding skipped");
			trace.SkipPhase("Collect target methods");
			trace.SkipPhase("Scan call sites");
			trace.SkipPhase("Resolve call symbols");
			trace.SkipPhase("Apply target filters");

			if (registry.AspectAttributes.Count == 0 && !externalAspectDefinitionsPossible)
			{
				trace.AddDecision("Fast path: no AspectAttribute definitions found.");
				trace.SkipPhase("Build target filters");
			}
			else
			{
				using (trace.TimePhase("Build target filters"))
				{
					var selection = new AspectSelectionService(compilation, options, registry, diagnosticSink, trace);

					selection.ReportDesignTimeFilterDiagnostics(appliedAttributes, cancellationToken);
				}
			}

			trace.SetCounter("Diagnostics reported", diagnosticSink.Diagnostics.Count);

			return new AnalysisResult(compilation, options, [], [..diagnosticSink.Diagnostics], trace);
		}

		static int CountAppliedAspectAttributes(
			Compilation                     compilation,
			AspectDefinitionRegistry        registry,
			ImmutableArray<AttributeSyntax> attributes,
			CancellationToken               cancellationToken)
		{
			var count = 0;

			foreach (var attribute in attributes)
			{
				if (cancellationToken.IsCancellationRequested)
					break;

				var semanticModel = compilation.GetSemanticModel(attribute.SyntaxTree);

				if (semanticModel.GetSymbolInfo(attribute, cancellationToken).Symbol is not IMethodSymbol { ContainingType: var attributeClass })
					continue;

				if (!registry.TryGetDefinition(attributeClass, out _))
					continue;

				if (!AspectSymbols.IsConditionalAspectEnabled(attributeClass, compilation, attribute.SyntaxTree))
					continue;

				count++;
			}

			return count;
		}

		static void ValidateAspectHooks(
			List<DiagnosticInfo>                                                     diagnostics,
			Dictionary<ISymbol,(AttributeSyntax Syntax,SemanticModel SemanticModel)> aspectAttributes,
			HashSet<string>                                                          reportedDiagnostics)
		{
			foreach (var item in aspectAttributes)
			{
				var symbol          = item.Key;
				var aspectAttribute = item.Value;

				if (symbol is not INamedTypeSymbol aspectClass)
					continue;

				foreach (var arg in aspectAttribute.Syntax.ArgumentList?.Arguments ?? default)
				{
					if (arg.NameEquals?.Name.Identifier.ValueText is not (
					    "OnInit"            or
					    "OnUsing"           or "OnUsingAsync"      or
					    "OnBeforeCall"      or "OnBeforeCallAsync" or
					    "OnCall"            or
					    "OnAfterCall"       or "OnAfterCallAsync"  or
					    "OnCatch"           or "OnCatchAsync"      or
					    "OnFinally"         or "OnFinallyAsync"))
						continue;

					if (AspectSymbols.GetAttributeArgumentValue(arg.Expression, aspectAttribute.SemanticModel) is not string hookName || string.IsNullOrWhiteSpace(hookName))
						continue;

					var methods = GetHookCandidates(aspectClass, hookName).ToArray();

					if (methods.Length == 0)
					{
						ReportDiagnostic(
							diagnostics,
							reportedDiagnostics,
							AspectDiagnosticID.HookMethodNotFound,
							$"Aspect hook method '{hookName}' was not found on aspect type '{aspectClass.ToDisplayString()}'.",
							arg.Expression.GetLocation());
					}
					else if (!methods.Any(static m => m.IsStatic))
					{
						ReportDiagnostic(
							diagnostics,
							reportedDiagnostics,
							AspectDiagnosticID.HookMethodNotStatic,
							$"Aspect hook method '{hookName}' on aspect type '{aspectClass.ToDisplayString()}' must be static.",
							arg.Expression.GetLocation());
					}
				}
			}
		}

		static void ReportDiagnostics(SourceProductionContext spc, AnalysisResult analysis)
		{
			if (analysis.Options.GenerateApi)
				spc.AddSource("AspectAttribute.g.cs", SourceText.From(GenerateAspectApiText(analysis.Options.PublicApi), Encoding.UTF8));

			foreach (var diagnostic in analysis.Diagnostics)
			{
				spc.ReportDiagnostic(
					Diagnostic.Create(
						diagnostic.Id,
						"AspectGenerator",
						diagnostic.Message,
						diagnostic.Severity,
						diagnostic.Severity,
						IsEnabledByDefault(diagnostic.Id),
						diagnostic.Severity == DiagnosticSeverity.Error ? 0 : 1,
						location: diagnostic.Location));
			}

			AspectBuildReport.Write(analysis);
		}

		/// <summary>
		/// AG0006 lists every call a target filter selected and the generator left as it is; it is off by default, and
		/// AG0007 summarizes those calls per reason instead (see <see cref="AspectDiagnostics.GetFilterSelectedCallsNotInterceptedMessage"/>).
		/// </summary>
		static bool IsEnabledByDefault(string id)
		{
			return id != AspectDiagnosticID.FilterSelectedCallNotIntercepted;
		}

		static void EmitInterceptors(SourceProductionContext spc, AnalysisResult analysis)
		{
			if (!analysis.Options.EmitInterceptors ||
				analysis.AspectedMethods.Length == 0 ||
				spc.CancellationToken.IsCancellationRequested)
				return;

			GenerateSource(spc, analysis.Compilation, analysis.Options, analysis.AspectedMethods);
		}

		static string GetInterceptorsNamespace(GeneratorExecutionOptions options)
		{
			return string.IsNullOrWhiteSpace(options.InterceptorsNamespace) ? "AspectGenerator" : options.InterceptorsNamespace!;
		}

		static void ReportBuildPropsNotImported(List<DiagnosticInfo> diagnostics)
		{
			diagnostics.Add(
				new DiagnosticInfo(
				AspectDiagnosticID.BuildPropsNotImported,
				"AspectGenerator is running without its MSBuild props (the AspectGeneratorPropsImported property is not set), so InterceptorsNamespaces and the generator options are missing and the generated interceptors may not compile. " +
				"Reference the AspectGenerator package from this project (<PackageReference Include=\"AspectGenerator\" PrivateAssets=\"all\" />) instead of receiving the analyzer from a library or adding it by hand; " +
				"a library that ships aspects can pass the generator on to its consumers with PrivateAssets=\"none\" on its own reference.",
				Location.None,
				DiagnosticSeverity.Warning));
		}

		static bool IsInterceptorsNamespaceListed(GeneratorExecutionOptions options)
		{
			if (string.IsNullOrWhiteSpace(options.InterceptorsNamespaces))
				return false;

			return options.InterceptorsNamespaces!
				.Split([';'], StringSplitOptions.RemoveEmptyEntries)
				.Select(static n => n.Trim())
				.Contains(GetInterceptorsNamespace(options), StringComparer.Ordinal);
		}

		static void ReportMissingInterceptorsNamespace(List<DiagnosticInfo> diagnostics, GeneratorExecutionOptions options)
		{
			var interceptorsNamespace = GetInterceptorsNamespace(options);

			if (string.IsNullOrWhiteSpace(options.InterceptorsNamespaces))
			{
				diagnostics.Add(
					new DiagnosticInfo(
					AspectDiagnosticID.NamespaceNotAllowed,
					$"InterceptorsNamespaces MSBuild property is empty. Generated interceptors namespace '{interceptorsNamespace}' must be listed there.",
					Location.None,
					DiagnosticSeverity.Warning));

				return;
			}

			if (IsInterceptorsNamespaceListed(options))
				return;

			diagnostics.Add(
				new DiagnosticInfo(
				AspectDiagnosticID.NamespaceNotAllowed,
				$"Generated interceptors namespace '{interceptorsNamespace}' is not listed in the InterceptorsNamespaces MSBuild property.",
				Location.None,
				DiagnosticSeverity.Warning));
		}

		internal static IEnumerable<(string Key, object? Value)> GetAspectOptions(AttributeInfo attribute)
		{
			if (attribute.AspectDefinitionData is {} aspectAttributeData)
				return aspectAttributeData.NamedArguments.Select(static arg => (
					arg.Key,
					arg.Value.Kind == TypedConstantKind.Array ? arg.Value.Values.Select(static v => v.Value).ToArray() : arg.Value.Value));

			if (attribute is { AspectDefinitionSyntax: {} syntax, AspectDefinitionSemanticModel: {} semanticModel })
				return GetOptions(syntax, semanticModel);

			return [];

			static IEnumerable<(string Key, object? Value)> GetOptions(AttributeSyntax attribute, SemanticModel semanticModel)
			{
				foreach (var arg in attribute.ArgumentList?.Arguments ?? default)
					if (arg.NameEquals is not null)
					{
						var name = arg.NameEquals.Name.Identifier.ValueText;

						var attributeArgumentValue = AspectSymbols.GetAttributeArgumentValue(arg.Expression, semanticModel);
						yield return (
							name,
							name == "Lifetime"
								? attributeArgumentValue ?? arg.Expression.ToString().Split('.').LastOrDefault()
								: attributeArgumentValue);
					}
			}
		}

		static void ReportDiagnostic(List<DiagnosticInfo> diagnostics, HashSet<string> reportedDiagnostics, string id, string message, Location? location)
		{
			var key = $"{id}:{location?.SourceTree?.FilePath}:{location?.SourceSpan.Start}:{message}";

			if (!reportedDiagnostics.Add(key))
				return;

			diagnostics.Add(new DiagnosticInfo(id, message, location));
		}

		static string GetAppliedAspectConstruction(AttributeInfo attribute)
		{
			var attributeType = attribute.AttributeClass.ToDisplayString(SymbolDisplayFormat.FullyQualifiedFormat);

			if (AspectSymbols.GetAppliedAttributeData(attribute) is {} data)
			{
				// A null keeps its type here even when it is object: the constructor overload depends on it.
				var constructorArguments = data.ConstructorArguments
					.Select(static c => c is { Kind: TypedConstantKind.Primitive, Value: null, Type.SpecialType: SpecialType.System_Object } ? "(object)null" : PrintTypedConstant(c))
					.ToArray();
				var namedArguments = data.NamedArguments
					.Where(static arg => arg.Key != "TargetFilter")
					.Select(static arg => $"{arg.Key} = {PrintTypedConstant(arg.Value)}")
					.ToArray();

				return CreateAttributeConstruction(attributeType, constructorArguments, namedArguments);
			}

			if (attribute is { AppliedAttributeSyntax: {} syntax, AppliedSemanticModel: {} semanticModel })
			{
				var constructorArguments = new List<string>();
				var namedArguments       = new List<string>();

				foreach (var arg in syntax.ArgumentList?.Arguments ?? default)
				{
					var value = AspectSymbols.GetAttributeArgumentValue(arg.Expression, semanticModel);
					var type  = semanticModel.GetTypeInfo(arg.Expression).ConvertedType ?? semanticModel.GetTypeInfo(arg.Expression).Type;

					if (arg.NameEquals is null)
					{
						constructorArguments.Add(PrintAttributeValue(value, type));
						continue;
					}

					var name = arg.NameEquals.Name.Identifier.ValueText;

					if (name != "TargetFilter")
						namedArguments.Add($"{name} = {PrintAttributeValue(value, type)}");
				}

				return CreateAttributeConstruction(attributeType, constructorArguments, namedArguments);
			}

			return $"new {attributeType}()";

			static string CreateAttributeConstruction(string attributeType, IReadOnlyCollection<string> constructorArguments, IReadOnlyCollection<string> namedArguments)
			{
				var result = $"new {attributeType}({string.Join(", ", constructorArguments)})";

				if (namedArguments.Count > 0)
					result += $" {{ {string.Join(", ", namedArguments)} }}";

				return result;
			}
		}

		/// <summary>
		/// An attribute argument as an expression of exactly the type the attribute model gives it, so that a parameter,
		/// property or array element of type <c>object</c> receives the same boxed value as the attribute itself: an enum
		/// keeps its enum type, a byte or short its own type, an element of an <c>object[]</c> its own type (an array,
		/// a <c>typeof</c>, a null), recursively.
		/// </summary>
		static string PrintTypedConstant(TypedConstant value)
		{
			switch (value.Kind)
			{
				case TypedConstantKind.Array when value.Type is IArrayTypeSymbol arrayType :
					if (value.IsNull)
						return $"({PrintType(arrayType)})null";

					// new T[0] cannot be written for an array of arrays (new int[0][] is); an empty initializer can.
					if (value.Values.Length == 0)
						return arrayType.ElementType is IArrayTypeSymbol
							? $"new {PrintType(arrayType)} {{ }}"
							: $"new {PrintType(arrayType.ElementType)}[0]";

					return $"new {PrintType(arrayType)} {{ {string.Join(", ", value.Values.Select(PrintTypedConstant))} }}";

				case TypedConstantKind.Type :
					return value.Value is ITypeSymbol type ? $"typeof({PrintType(type)})" : "(global::System.Type)null";

				case TypedConstantKind.Enum when value.Type is {} enumType :
					return PrintCast(enumType, PrintValue(value.Value, null));

				// A typed null keeps its type, which can pick the constructor overload; an object null has nothing to keep.
				case TypedConstantKind.Primitive when value.Value is null :
					return value.Type is { SpecialType: not SpecialType.System_Object } nullType ? $"({PrintType(nullType)})null" : "null";

				// These have no literal suffix: without the cast, an object slot would receive an int.
				case TypedConstantKind.Primitive when value.Value is byte or sbyte or short or ushort :
					return PrintCast(value.Type!, PrintValue(value.Value, null));

				default :
					return PrintValue(value.Value, value.Type);
			}
		}

		/// <summary>
		/// A cast of a literal; a negative one needs parentheses (<c>(T)-1</c> parses as a subtraction).
		/// </summary>
		static string PrintCast(ITypeSymbol type, string literal)
		{
			return literal.StartsWith("-", StringComparison.Ordinal)
				? $"({PrintType(type)})({literal})"
				: $"({PrintType(type)}){literal}";
		}

		static string PrintAttributeValue(object? value, ITypeSymbol? type)
		{
			if (type is IArrayTypeSymbol arrayType && value is object?[] values)
				return values.Length switch
				{
					0 => $"new {PrintType(arrayType.ElementType)}[0]",
					_ => $"new {PrintType(arrayType)} {{ {values.Select(v => PrintValue(v, arrayType.ElementType)).Aggregate((v1, v2) => $"{v1}, {v2}")} }}"
				};

			return PrintValue(value, type);
		}

		static void GenerateSource(
			SourceProductionContext            spc,
			Compilation                        compilation,
			GeneratorExecutionOptions          options,
			ImmutableArray<AnalyzedInvocation> aspectedMethods)
		{
			var interceptorsNamespace = GetInterceptorsNamespace(options);
			var semanticModels        = new Dictionary<SyntaxTree,SemanticModel>();
			var compilerRejectedCalls = 0;

			// Generate source. One file for all the interceptors.
			// Interceptors.g.cs
			//
			var sb = new StringBuilder(
				$$"""
				// <auto-generated/>
				#pragma warning disable
				#nullable enable

				using System;

				using SR  = System.Reflection;
				using SLE = System.Linq.Expressions;

				namespace System.Runtime.CompilerServices
				{
					[AttributeUsage(AttributeTargets.Method, AllowMultiple = true)]
					file sealed class InterceptsLocationAttribute(int version, string data) : Attribute
					{
					}
				}

				namespace {{interceptorsNamespace}}
				{
					using AspectGenerator = AspectGenerator;

					file static class AspectGeneratorInterceptors
					{
						static SR.MethodInfo GetMethodInfo(SLE.Expression expr)
						{
							return expr switch
							{
								SLE.MethodCallExpression mc => mc.Method,
								_                           => throw new InvalidOperationException()
							};
						}

						static SR.MethodInfo MethodOf<T>(SLE.Expression<Func<T>> func) => GetMethodInfo(func.Body);
						static SR.MethodInfo MethodOf   (SLE.Expression<Action>  func) => GetMethodInfo(func.Body);


				""");

			foreach (var interceptor in InterceptorNamingService.Create(aspectedMethods))
			{
				var method          = interceptor.Method;
				var interceptorName = interceptor.Name;
				var methods         = interceptor.Invocations;
				var attributes      = interceptor.Attributes;
				var typeParameters  = interceptor.TypeParameters;
				var typeArguments   = InterceptorShape.PrintTypeParameterList(typeParameters);
				var constraints     = InterceptorShape.PrintConstraints(typeParameters, PrintType);
				var unsafeModifier  = InterceptorShape.HasPointerTypes(method) ? "unsafe " : "";

				// A generic interceptor keeps what depends on its type arguments (the target method info) in a generic state
				// class, and the aspect instances in the non-generic one, so they stay one per interceptor.
				if (typeParameters.Count > 0)
				{
					sb.AppendLine(
						$$"""
								private static {{unsafeModifier}}class {{interceptorName}}_State{{typeArguments}}{{constraints}}
								{
						""");

					AppendTargetMethod(method, interceptorName);

					sb.AppendLine(
						"""
								}

						""");
				}

				sb.AppendLine(
					$$"""
							private static {{(typeParameters.Count == 0 ? unsafeModifier : "")}}class {{interceptorName}}_State
							{
					""");

				if (typeParameters.Count == 0)
					AppendTargetMethod(method, interceptorName);

				for (var i = 0; i < attributes.Count; i++)
				{
					var attr = attributes[i];

					if (AspectLifetimeResolver.UsesInstanceLifetime(attr))
						continue;

					var attrType = attr.AttributeClass.ToDisplayString(SymbolDisplayFormat.FullyQualifiedFormat);

					sb.AppendLine($"\t\t\tinternal static readonly {attrType} Aspect{i} = {GetAppliedAspectConstruction(attr)};");
				}

				sb.AppendLine(
					$$"""

								static {{interceptorName}}_State()
								{
								}
							}
					""");

				sb.AppendLine(
					$$"""
							//
							/// <summary>
							/// Intercepts {{SingleLine(method.ToDisplayString())}}.
							/// </summary>
							//
					""");

				foreach (var analyzedInvocation in methods)
				{
					var inv = analyzedInvocation.Inv;

					sb.AppendLine(
						$"""
								// Intercepts {SingleLine(inv.ToString())}.
						""");

					void AppendInterceptsLocation(InvocationExpressionSyntax invocation)
					{
						if (!semanticModels.TryGetValue(invocation.SyntaxTree, out var semantic))
						{
							semantic = compilation.GetSemanticModel(invocation.SyntaxTree);
							semanticModels.Add(invocation.SyntaxTree, semantic);
						}

						// GetInterceptableLocation appeared in Roslyn 4.11 and is marked experimental before 4.14. The generator's
						// floor is 4.12 all the same, because the compiler reads the InterceptorsNamespaces key from 4.12 on.
#pragma warning disable RSEXPERIMENTAL002
						var location = semantic.GetInterceptableLocation(invocation, spc.CancellationToken);
#pragma warning restore RSEXPERIMENTAL002

						if (location is null)
						{
							// The same rule as for calls the generator cannot express: AG0003 for an aspect applied to the
							// target, AG0006 (information, off by default, summarized by AG0007) for a call only a target
							// filter selected.
							var isApplied  = InterceptorShape.IsAppliedToTarget(analyzedInvocation.Method, analyzedInvocation.Attributes);
							var id         = isApplied ? AspectDiagnosticID.CannotIntercept : AspectDiagnosticID.FilterSelectedCallNotIntercepted;
							var descriptor = new DiagnosticDescriptor(
								id,
								"AspectGenerator",
								$"Invocation '{SingleLine(invocation.ToString())}' cannot be intercepted by the compiler.",
								"AspectGenerator",
								isApplied ? DiagnosticSeverity.Warning : DiagnosticSeverity.Info,
								IsEnabledByDefault(id));

							if (!isApplied)
								compilerRejectedCalls++;

							spc.ReportDiagnostic(
								Diagnostic.Create(descriptor, invocation.GetLocation()));
							return;
						}

#pragma warning disable RSEXPERIMENTAL002
						sb.Append("\t\t").AppendLine(location.GetInterceptsLocationAttributeSyntax());
#pragma warning restore RSEXPERIMENTAL002
					}

					switch (inv.Expression)
					{
						case MemberAccessExpressionSyntax  : AppendInterceptsLocation(inv); break;
						case IdentifierNameSyntax          : AppendInterceptsLocation(inv); break;
						case GenericNameSyntax             : AppendInterceptsLocation(inv); break;
						case MemberBindingExpressionSyntax : AppendInterceptsLocation(inv); break;
						default :
							sb.AppendLine(
								$"""
										#error Unknown expression type {inv.Expression.GetType()} for : {SingleLine(inv.Expression.ToString())}
								""");
							break;
					}

					sb.AppendLine(
						"""
								//
						""");
				}

				sb.AppendLine("\t\t[global::System.Runtime.CompilerServices.CompilerGenerated]");

				if (options.DebuggerStepThrough)
					sb.AppendLine("\t\t[global::System.Diagnostics.DebuggerStepThrough]");

				sb.Append(InterceptorShape.HasPointerTypes(method) ? "\t\tpublic static unsafe " : "\t\tpublic static ");

				var methodModifierPosition = sb.Length;

				sb
					.AppendLine(
						$$"""
						{{PrintType(method.ReturnType)}} {{interceptorName}}{{typeArguments}}({{PrintParameters(method)}}){{constraints}}
								{
						""")
					;

				GenerateMethodBody(spc, sb, methods[0].Inv, method, interceptorName, typeArguments, attributes, methodModifierPosition, compilation);

				sb
					.AppendLine(
						"""
								}
						""")
					.AppendLine();
			}

			TrimEnd(sb);

			sb
				.AppendLine(
					"""
						}
					}
					""");

			spc.AddSource("Interceptors.g.cs", SourceText.From(sb.ToString(), Encoding.UTF8));

			if (compilerRejectedCalls > 0)
				spc.ReportDiagnostic(
					Diagnostic.Create(
						AspectDiagnosticID.FilterSelectedCallsNotIntercepted,
						"AspectGenerator",
						AspectDiagnostics.GetFilterSelectedCallsNotInterceptedMessage(compilerRejectedCalls, "the compiler cannot intercept the call"),
						DiagnosticSeverity.Info,
						DiagnosticSeverity.Info,
						true,
						1,
						location: Location.None));

			void AppendTargetMethod(IMethodSymbol method, string interceptorName)
			{
				if (InterceptorShape.RequiresReflectionLookup(method))
				{
					var (expression, delegateDeclaration) = GetTargetMethodByReflection(method);

					if (delegateDeclaration is not null)
						sb.AppendLine($"\t\t\t{delegateDeclaration}").AppendLine();

					sb.AppendLine(
						$$"""
									internal static readonly global::System.Reflection.MemberInfo TargetMethod = {{expression}};

						""");
					return;
				}

				var parametersAdded = false;

				foreach (var p in method.Parameters)
				{
					switch (p.RefKind)
					{
						case RefKind.Ref :
						case RefKind.Out :
						case RefKind.In  :
							sb.AppendLine(
								$$"""
											static {{PrintType(p.Type)}} {{interceptorName}}_Arg_{{p.Name}} = default({{PrintType(p.Type)}});
								""");
							parametersAdded = true;
							break;
					}
				}

				if (parametersAdded)
					sb.AppendLine();

				sb.AppendLine(
					$$"""
								internal static readonly global::System.Reflection.MemberInfo TargetMethod = MethodOf{{GetMethodOf(method, interceptorName)}};

					""");
			}
		}

		/// <summary>
		/// Checks the hooks of the aspects of one target and returns the aspects whose generated hook call would not
		/// compile: a called hook that is missing, not static, has no valid parameter list or does not match OnCall, or whose
		/// return type the generated statement cannot use (OnInit assigns it, OnUsing disposes it, an async hook awaits it).
		/// Those aspects are left out of the interceptor, so the build reports the AG01xx diagnostic instead of compiler
		/// errors in the generated file, and the other aspects of the target still apply when the diagnostic is lowered. A
		/// synchronous hook with a non-void return type is called as a statement, which compiles; it stays.
		/// </summary>
		static List<AttributeInfo> ValidateAspectHooksForMethod(
			List<DiagnosticInfo>    diagnostics,
			Compilation             compilation,
			string?                 targetFramework,
			InvocationExpressionSyntax invocationExpression,
			IMethodSymbol           targetMethod,
			List<AttributeInfo>     attributes,
			HashSet<string>         reportedDiagnostics,
			IteratorOverrideIndex   iteratorIndex)
		{
			var targetIsAsync    = IsSupportedAsyncReturnType(targetMethod.ReturnType, out var asyncResultType);
			var generateAsync    = GeneratesAsyncInterceptor(targetMethod, attributes);
			var iterators        = (List<IMethodSymbol>?)null;
			var dropped          = new List<AttributeInfo>();

			for (var idx = 0; idx < attributes.Count; idx++)
			{
				var attribute       = attributes[idx];
				var aspectArguments = GetAspectOptions(attribute).ToDictionary(static a => a.Key, static a => a.Value);
				var useInterceptData = aspectArguments.TryGetValue("UseInterceptData", out var useData) && useData is true;

				var calledHooks     = GetCalledHookOptions(aspectArguments, generateAsync).ToList();
				var hookFailed      = false;
				var aspectType      = InterceptorShape.GetAspectTypeAsWritten(attribute.AttributeClass, compilation);

				// Only aspects with hooks that would surround the body need to know which iterators the call can run (the
				// override index behind it is built once per run, on first use).
				if (_bodyHooks.Any(h => aspectArguments.TryGetValue(h, out var value) && value is string s && !string.IsNullOrWhiteSpace(s)) &&
					(iterators ??= iteratorIndex.GetIteratorsTheCallCanRun(targetMethod)).Count > 0)
					ReportIteratorBodyNotCovered(diagnostics, reportedDiagnostics, invocationExpression, targetMethod, iterators, attribute, aspectArguments);

				if (idx < attributes.Count - 1 &&
					aspectArguments.TryGetValue("OnCall", out var onCallValue) &&
					onCallValue is string onCall &&
					!string.IsNullOrWhiteSpace(onCall))
				{
					if (attribute.AppliedAttributeData?.ApplicationSyntaxReference is {} asr)
					{
						ReportDiagnostic(
							diagnostics,
							reportedDiagnostics,
							AspectDiagnosticID.OnCallNotLastAspect,
							$"Aspect '{attribute.AttributeClass}' specifies 'OnCall' interceptor and has to be the last one in aspect list.",
							Location.Create(asr.SyntaxTree, asr.Span));
					}
					else
					{
						ReportDiagnostic(
							diagnostics,
							reportedDiagnostics,
							AspectDiagnosticID.OnCallNotLastMethod,
							$"Method '{targetMethod}' is decorated with an aspect that specifies 'OnCall' interceptor. This aspect has to be the last one in aspect list.",
							Location.Create(invocationExpression.SyntaxTree, invocationExpression.Span));
					}
				}

				foreach (var hook in _hookContracts)
				{
					if (!aspectArguments.TryGetValue(hook.Name, out var hookNameValue) ||
						hookNameValue is not string hookName ||
						string.IsNullOrWhiteSpace(hookName))
						continue;

					var location = GetHookLocation(attribute, hook.Name, invocationExpression);

					var isCalled = calledHooks.Contains(hook.Name);

					// Not called by this interceptor, so nothing is dropped for it.
					if (hook.IsAsync && !targetIsAsync && !HasSyncFallback(aspectArguments, hook.Name))
					{

						var asyncVoidMessage = targetMethod is { IsAsync: true, ReturnsVoid: true }
							? " Async void target methods are not supported."
							: "";

						ReportDiagnostic(
							diagnostics,
							reportedDiagnostics,
							AspectDiagnosticID.AsyncHookRequiresTask,
							$"Async hook '{hook.Name}' requires target method '{targetMethod.ToDisplayString()}' to return Task, Task<T>, ValueTask, or ValueTask<T>, or a synchronous fallback hook to be specified.{asyncVoidMessage}",
							location);
					}

					// The overloads the generated call can bind to: for a hook this interceptor calls, the accessible ones only
					// (a call whose hook exists but is not accessible at all was skipped with AG0003 before).
					var methods = GetHookCandidates(aspectType, hookName)
						.Where(m => !isCalled || InterceptorShape.IsAccessibleFromInterceptors(m, compilation))
						.ToArray();
					var staticMethods = methods.Where(static m => m.IsStatic).ToArray();

					if (methods.Length == 0)
					{
						hookFailed |= isCalled;

						// A referenced assembly's metadata shows no members it does not expose to this one.
						var notFound = aspectType.DeclaringSyntaxReferences.Length == 0
							? "was not found, or is not accessible from this assembly, on"
							: "was not found on";

						ReportDiagnostic(
							diagnostics,
							reportedDiagnostics,
							AspectDiagnosticID.HookMethodNotFound,
							$"Aspect hook method '{hookName}' {notFound} aspect type '{attribute.AttributeClass.ToDisplayString()}'.",
							location);
						continue;
					}

					if (staticMethods.Length == 0)
					{
						hookFailed |= isCalled;

						ReportDiagnostic(
							diagnostics,
							reportedDiagnostics,
							AspectDiagnosticID.HookMethodNotStatic,
							$"Aspect hook method '{hookName}' on aspect type '{attribute.AttributeClass.ToDisplayString()}' must be static.",
							location);
						continue;
					}

					if (hook.Name == "OnCall")
					{
						if (!staticMethods.Any(m => IsValidOnCallHook(compilation, m, targetMethod, targetIsAsync, asyncResultType)))
						{
							hookFailed |= isCalled;

							ReportDiagnostic(
								diagnostics,
								reportedDiagnostics,
								AspectDiagnosticID.OnCallHookMismatch,
								$"OnCall hook '{hookName}' on aspect type '{attribute.AttributeClass.ToDisplayString()}' must match target method '{targetMethod.ToDisplayString()}'.",
								location);
						}

						continue;
					}

					var methodsWithValidParameters = staticMethods
						.Where(m => IsValidLifecycleHookParameter(m, targetMethod, targetIsAsync, asyncResultType, useInterceptData, aspectType))
						.ToArray();

					if (methodsWithValidParameters.Length == 0)
					{
						hookFailed |= isCalled;

						var diagnosticId = useInterceptData ? AspectDiagnosticID.HookRequiresInterceptData : AspectDiagnosticID.HookInvalidParameters;

						ReportDiagnostic(
							diagnostics,
							reportedDiagnostics,
							diagnosticId,
							diagnosticId == AspectDiagnosticID.HookRequiresInterceptData
								? $"UseInterceptData=true requires hook method '{hookName}' to accept ref InterceptData<T> for '{hook.Name}'. Candidates: {string.Join("; ", staticMethods.Select(static m => m.ToDisplayString(SymbolDisplayFormat.CSharpErrorMessageFormat)))}."
								: $"Hook method '{hookName}' on aspect type '{attribute.AttributeClass.ToDisplayString()}' has an invalid parameter list for '{hook.Name}'. Candidates: {string.Join("; ", staticMethods.Select(static m => m.ToDisplayString(SymbolDisplayFormat.CSharpErrorMessageFormat)))}.",
							location);
						continue;
					}

					// A return type the compiler cannot resolve is already an error of its own (CS0246, for example ValueTask
					// on a target framework without it); AG0104 on top would only repeat it with a less precise cause.
					if (!methodsWithValidParameters.Any(m => IsValidLifecycleHookReturnType(m, hook, targetMethod, targetIsAsync, asyncResultType, useInterceptData)) &&
						!methodsWithValidParameters.Any(static m => HasUnresolvedReturnType(m)))
					{
						hookFailed |= isCalled && (hook.IsAsync || hook.Name is "OnInit" or "OnUsing");

						ReportDiagnostic(
							diagnostics,
							reportedDiagnostics,
							AspectDiagnosticID.HookInvalidReturnType,
							$"Hook method '{hookName}' on aspect type '{attribute.AttributeClass.ToDisplayString()}' has an invalid return type for '{hook.Name}': {GetExpectedHookReturnType(hook, useInterceptData, compilation, targetFramework)}.",
							location);
					}
				}

				if (hookFailed)
					dropped.Add(attribute);
			}

			return dropped;

			static bool HasSyncFallback(Dictionary<string,object?> aspectArguments, string asyncHookName)
			{
				var syncHookName = asyncHookName.EndsWith("Async", StringComparison.Ordinal)
					? asyncHookName[..^5]
					: asyncHookName;

				return syncHookName != asyncHookName &&
					aspectArguments.TryGetValue(syncHookName, out var value) &&
					value is string s &&
					!string.IsNullOrWhiteSpace(s);
			}
		}

		/// <summary>
		/// The interceptor wraps the call, and the call of an iterator only creates the sequence: the iterator body runs
		/// later, while the caller enumerates it. Hooks that are meant to surround the body (OnAfterCall, OnCatch, OnFinally and
		/// OnUsing) then run before any of it, and an exception thrown by the body never reaches
		/// OnCatch. The interception still happens as written, so this is reported rather than skipped: a warning at the
		/// aspect applied to the iterator, information at the call when only a target filter selected it.
		/// </summary>
		static void ReportIteratorBodyNotCovered(
			List<DiagnosticInfo>       diagnostics,
			HashSet<string>            reportedDiagnostics,
			InvocationExpressionSyntax invocationExpression,
			IMethodSymbol              targetMethod,
			List<IMethodSymbol>        iterators,
			AttributeInfo              attribute,
			Dictionary<string,object?> aspectArguments)
		{
			var hooks = _bodyHooks
				.Where(name => aspectArguments.TryGetValue(name, out var value) && value is string s && !string.IsNullOrWhiteSpace(s))
				.ToList();

			if (hooks.Count == 0)
				return;

			// An aspect applied in source is reported where it is applied; one applied in a referenced assembly, at the call.
			var isApplied = InterceptorShape.IsAppliedToTarget(targetMethod, [attribute]);
			var location  = isApplied && attribute.AppliedAttributeData?.ApplicationSyntaxReference is {} asr
				? Location.Create(asr.SyntaxTree, asr.Span)
				: invocationExpression.GetLocation();
			// The declaration, not the constructed or reduced form the call binds: one attribute, one warning.
			var declared  = (targetMethod.ReducedFrom ?? targetMethod).OriginalDefinition;
			var subject   = iterators is [var only] && SymbolEqualityComparer.Default.Equals(only, declared)
				? $"iterator method '{declared.ToDisplayString()}'"
				: $"method '{declared.ToDisplayString()}', whose call can run the iterator {string.Join(", ", iterators.Select(static i => $"'{i.ToDisplayString()}'"))}";
			var message   =
				$"Aspect '{attribute.AttributeClass.ToDisplayString()}' on {subject}: " +
				$"{string.Join(", ", hooks)} {(hooks.Count == 1 ? "runs" : "run")} when the call returns the sequence, before the iterator body runs. " +
				"Exceptions thrown and work done while the sequence is enumerated do not reach the aspect. " +
				"Apply the aspect to a method that enumerates the sequence, or return a materialized collection.";
			var key       = $"{AspectDiagnosticID.IteratorBodyNotCovered}:{location.SourceTree?.FilePath}:{location.SourceSpan.Start}:{attribute.AttributeClass.ToDisplayString()}";

			if (reportedDiagnostics.Add(key))
				diagnostics.Add(new DiagnosticInfo(AspectDiagnosticID.IteratorBodyNotCovered, message, location, isApplied ? DiagnosticSeverity.Warning : DiagnosticSeverity.Info));
		}

		// An iterator does not return a task, so its interceptor calls the synchronous hooks only (an async hook without
		// a synchronous fallback is AG0107).
		static readonly string[] _bodyHooks =
		[
			"OnUsing",
			"OnAfterCall",
			"OnCatch",
			"OnFinally",
		];

		/// <summary>
		/// The generator's own API types (InterceptInfo, InterceptData) are unresolved in the compilation it reads when it
		/// generates them itself, so they do not count.
		/// </summary>
		static bool HasUnresolvedReturnType(IMethodSymbol method)
		{
			if (method.ReturnType is not IErrorTypeSymbol errorType)
				return false;

			// As written: InterceptInfo, InterceptInfo<T>, AspectGenerator.InterceptInfo...; Missing.InterceptInfo is not ours.
			var name = errorType.ToDisplayString(SymbolDisplayFormat.CSharpErrorMessageFormat);

			if (name.StartsWith("AspectGenerator.", StringComparison.Ordinal))
				name = name.Substring("AspectGenerator.".Length);

			var isOwnType =
				name is "InterceptInfo" or "InterceptData" ||
				name.StartsWith("InterceptInfo<", StringComparison.Ordinal) ||
				name.StartsWith("InterceptData<", StringComparison.Ordinal);

			return !isOwnType;
		}

		/// <summary>
		/// What the hook has to return, for the AG0104 message. An async hook names the task types the compilation has:
		/// a target framework without ValueTask (.NET Framework, netstandard2.0 without System.Threading.Tasks.Extensions)
		/// leaves only Task.
		/// </summary>
		static string GetExpectedHookReturnType(HookContract hook, bool useInterceptData, Compilation compilation, string? targetFramework)
		{
			switch (hook.Name)
			{
				case "OnInit"       : return useInterceptData ? "it must return InterceptData<T>" : "it must return InterceptInfo<T>";
				case "OnUsing"      : return "it must return a type that implements System.IDisposable";
				case "OnUsingAsync" : return "it must return a type that implements System.IAsyncDisposable";
			}

			if (!hook.IsAsync)
				return "it must return void";

			if (compilation.GetTypeByMetadataName("System.Threading.Tasks.ValueTask") is not null)
				return "an async hook must return System.Threading.Tasks.Task or System.Threading.Tasks.ValueTask";

			var framework = string.IsNullOrEmpty(targetFramework) ? "this target framework" : $"target framework '{targetFramework}'";

			return $"an async hook must return System.Threading.Tasks.Task; ValueTask is not available on {framework} unless the System.Threading.Tasks.Extensions package is referenced";
		}

		internal readonly record struct HookContract(string Name, bool IsAsync);

		static readonly HookContract[] _hookContracts =
		[
			new ("OnInit",            false),
			new ("OnUsing",           false),
			new ("OnUsingAsync",      true),
			new ("OnBeforeCall",      false),
			new ("OnBeforeCallAsync", true),
			new ("OnCall",            false),
			new ("OnAfterCall",       false),
			new ("OnAfterCallAsync",  true),
			new ("OnCatch",           false),
			new ("OnCatchAsync",      true),
			new ("OnFinally",         false),
			new ("OnFinallyAsync",    true),
		];

		/// <summary>
		/// Whether the interceptor of a call is async: the target returns a task and one of its aspects names an async hook.
		/// </summary>
		internal static bool GeneratesAsyncInterceptor(IMethodSymbol method, List<AttributeInfo> attributes)
		{
			return IsSupportedAsyncReturnType(method.ReturnType, out _) &&
				attributes.Any(static d => GetAspectOptions(d).Any(static a => a.Key.EndsWith("Async", StringComparison.Ordinal) && a.Value is not null));
		}

		/// <summary>
		/// The hook options whose methods the interceptor calls, as the emitter chooses them: OnInit and OnCall as named,
		/// and of each pair the async form in an async interceptor when the aspect names it, the synchronous form otherwise.
		/// </summary>
		internal static IEnumerable<string> GetCalledHookOptions(IReadOnlyDictionary<string,object?> options, bool generateAsync)
		{
			foreach (var hook in _hookContracts)
			{
				if (!options.TryGetValue(hook.Name, out var value) || value is null)
					continue;

				if (hook.IsAsync)
				{
					if (generateAsync)
						yield return hook.Name;
				}
				else if (!(generateAsync && options.TryGetValue(hook.Name + "Async", out var asyncValue) && asyncValue is not null))
					yield return hook.Name;
			}
		}

		/// <summary>
		/// The methods a generated call <c>Aspect.Hook(...)</c> looks up: those named like the hook on the aspect type
		/// and on its base types.
		/// </summary>
		internal static List<IMethodSymbol> GetHookCandidates(INamedTypeSymbol aspectType, string hookName)
		{
			var result = new List<IMethodSymbol>();

			for (var type = aspectType; type is not null; type = type.BaseType)
				result.AddRange(type.GetMembers(hookName).OfType<IMethodSymbol>());

			return result;
		}

		/// <summary>
		/// The overload of a lifecycle hook the interceptor calls: an accessible static one with a valid parameter list,
		/// one with a valid return type first, then the form that takes the aspect. The emitter passes the arguments of
		/// this overload, so the compiler binds the call to an overload the checks have seen.
		/// </summary>
		internal static IMethodSymbol? ResolveLifecycleHook(
			INamedTypeSymbol aspectType,
			string           hookOption,
			string           hookName,
			IMethodSymbol    targetMethod,
			bool             useInterceptData,
			Compilation      compilation)
		{
			var hook          = _hookContracts.FirstOrDefault(h => h.Name == hookOption);
			var targetIsAsync = IsSupportedAsyncReturnType(targetMethod.ReturnType, out var asyncResultType);

			return GetHookCandidates(aspectType, hookName)
				.Where(m => m.IsStatic &&
					InterceptorShape.IsAccessibleFromInterceptors(m, compilation) &&
					IsValidLifecycleHookParameter(m, targetMethod, targetIsAsync, asyncResultType, useInterceptData, aspectType))
				.OrderByDescending(m => IsValidLifecycleHookReturnType(m, hook, targetMethod, targetIsAsync, asyncResultType, useInterceptData))
				.ThenByDescending(static m => m.Parameters.Length)
				.FirstOrDefault();
		}

		static Location GetHookLocation(AttributeInfo attribute, string hookName, InvocationExpressionSyntax invocationExpression)
		{
			if (attribute is { AspectDefinitionSyntax: {} syntax, AspectDefinitionSemanticModel: not null })
			{
				foreach (var arg in syntax.ArgumentList?.Arguments ?? default)
					if (arg.NameEquals?.Name.Identifier.ValueText == hookName)
						return arg.Expression.GetLocation();
			}

			if (attribute.AspectDefinitionData?.ApplicationSyntaxReference is {} aspectSyntaxReference)
				return Location.Create(aspectSyntaxReference.SyntaxTree, aspectSyntaxReference.Span);

			if (attribute.AppliedAttributeData?.ApplicationSyntaxReference is {} attributeSyntaxReference)
				return Location.Create(attributeSyntaxReference.SyntaxTree, attributeSyntaxReference.Span);

			return invocationExpression.GetLocation();
		}

		static bool IsValidLifecycleHookParameter(
			IMethodSymbol hookMethod,
			IMethodSymbol targetMethod,
			bool          targetIsAsync,
			ITypeSymbol?  asyncResultType,
			bool          useInterceptData,
			INamedTypeSymbol aspectClass)
		{
			if (hookMethod.Parameters.Length is not (1 or 2))
				return false;

			var parameterIndex = 0;

			if (hookMethod.Parameters.Length == 2)
			{
				var aspectParameter = hookMethod.Parameters[0];

				// The interceptor passes the aspect itself, so a parameter of a base type of the aspect (a hook declared on a
				// generic base aspect, for one) or of an interface it implements binds as well.
				if (aspectParameter.RefKind != RefKind.None || !IsAspectParameterType(aspectParameter.Type, aspectClass))
					return false;

				parameterIndex = 1;
			}

			var parameter = hookMethod.Parameters[parameterIndex];

			if (useInterceptData)
			{
				if (parameter.RefKind != RefKind.Ref)
					return false;

				return IsInterceptDataType(parameter.Type, hookMethod, GetHookReturnValueType(targetMethod, targetIsAsync, asyncResultType));
			}

			return parameter.RefKind == RefKind.None &&
				(parameter.Type.TypeKind == TypeKind.Dynamic ||
				IsInterceptInfoType(parameter.Type, hookMethod, GetHookReturnValueType(targetMethod, targetIsAsync, asyncResultType), allowNonGeneric: true));
		}

		static bool IsAspectParameterType(ITypeSymbol parameterType, INamedTypeSymbol aspectClass)
		{
			for (var type = aspectClass; type is not null; type = type.BaseType)
				if (SymbolEqualityComparer.Default.Equals(type, parameterType))
					return true;

			return aspectClass.AllInterfaces.Any(i => SymbolEqualityComparer.Default.Equals(i, parameterType));
		}

		static bool IsValidLifecycleHookReturnType(
			IMethodSymbol hookMethod,
			HookContract  hook,
			IMethodSymbol targetMethod,
			bool          targetIsAsync,
			ITypeSymbol?  asyncResultType,
			bool          useInterceptData)
		{
			if (hook.Name == "OnInit")
				return useInterceptData
					? IsInterceptDataType(hookMethod.ReturnType, hookMethod, GetHookReturnValueType(targetMethod, targetIsAsync, asyncResultType))
					: IsInterceptInfoType(hookMethod.ReturnType, hookMethod, GetHookReturnValueType(targetMethod, targetIsAsync, asyncResultType), allowNonGeneric: false);

			if (hook.Name == "OnUsing")
				return ImplementsType(hookMethod.ReturnType, "System.IDisposable");

			if (hook.Name == "OnUsingAsync")
				return ImplementsType(hookMethod.ReturnType, "System.IAsyncDisposable");

			if (hook.IsAsync)
				return IsSupportedAsyncReturnType(hookMethod.ReturnType, out _);

			return hookMethod.ReturnsVoid;
		}

		static bool IsValidOnCallHook(
			Compilation   compilation,
			IMethodSymbol hookMethod,
			IMethodSymbol targetMethod,
			bool          targetIsAsync,
			ITypeSymbol?  asyncResultType)
		{
			var expectedParameters = GetOnCallParameters(targetMethod).ToArray();

			if (hookMethod.Parameters.Length != expectedParameters.Length)
				return false;

			for (var i = 0; i < expectedParameters.Length; i++)
			{
				var actual   = hookMethod.Parameters[i];
				var expected = expectedParameters[i];

				if (actual.RefKind != expected.RefKind)
					return false;

				if (!SymbolEqualityComparer.Default.Equals(actual.Type, expected.Type))
					return false;
			}

			if (targetMethod.ReturnsVoid)
				return hookMethod.ReturnsVoid;

			if (targetIsAsync)
				return IsSupportedAsyncReturnType(hookMethod.ReturnType, out var hookAsyncResultType) &&
					(asyncResultType is null && hookAsyncResultType is null ||
					 asyncResultType is not null &&
					 hookAsyncResultType is not null &&
					 SymbolEqualityComparer.Default.Equals(asyncResultType, hookAsyncResultType));

			return compilation.ClassifyConversion(hookMethod.ReturnType, targetMethod.ReturnType).IsImplicit;
		}

		static IEnumerable<(ITypeSymbol Type, RefKind RefKind)> GetOnCallParameters(IMethodSymbol targetMethod)
		{
			if (targetMethod.MethodKind == MethodKind.ReducedExtension || !targetMethod.IsStatic)
			{
				var receiverType = targetMethod.ReceiverType ?? targetMethod.ContainingType;

				if (receiverType is not null)
					yield return (receiverType, RefKind.None);
			}

			foreach (var parameter in targetMethod.Parameters)
				yield return (parameter.Type, parameter.RefKind);
		}

		static (ITypeSymbol? Type, bool IsVoid) GetHookReturnValueType(IMethodSymbol targetMethod, bool targetIsAsync, ITypeSymbol? asyncResultType)
		{
			if (targetMethod.ReturnsVoid || targetIsAsync && asyncResultType is null)
				return (null, true);

			return targetIsAsync ? (asyncResultType, false) : (targetMethod.ReturnType, false);
		}

		static bool IsInterceptInfoType(
			ITypeSymbol                    type,
			IMethodSymbol                  hookMethod,
			(ITypeSymbol? Type, bool IsVoid) expectedValueType,
			bool                           allowNonGeneric)
		{
			if (type is not INamedTypeSymbol namedType)
				return false;

			if (!IsAspectGeneratorType(namedType, "InterceptInfo"))
				return IsUnresolvedCarrierType(type, "InterceptInfo", allowNonGeneric);

			if (namedType.Arity == 0)
				return allowNonGeneric;

			return namedType is { Arity: 1, TypeArguments: [var valueType] } &&
				TypeArgumentMatches(valueType, hookMethod, expectedValueType);
		}

		static bool IsInterceptDataType(
			ITypeSymbol                    type,
			IMethodSymbol                  hookMethod,
			(ITypeSymbol? Type, bool IsVoid) expectedValueType)
		{
			if (type is not INamedTypeSymbol namedType)
				return false;

			if (!IsAspectGeneratorType(namedType, "InterceptData"))
				return IsUnresolvedCarrierType(type, "InterceptData", allowNonGeneric: false);

			return namedType is { Arity: 1, TypeArguments: [var valueType] } &&
				TypeArgumentMatches(valueType, hookMethod, expectedValueType);
		}

		static bool IsUnresolvedCarrierType(ITypeSymbol type, string name, bool allowNonGeneric)
		{
			var displayName = type.ToDisplayString(SymbolDisplayFormat.CSharpErrorMessageFormat);

			return allowNonGeneric && displayName == name ||
				displayName.StartsWith(name + "<", StringComparison.Ordinal);
		}

		static bool TypeArgumentMatches(
			ITypeSymbol                    type,
			IMethodSymbol                  hookMethod,
			(ITypeSymbol? Type, bool IsVoid) expectedValueType)
		{
			if (type is ITypeParameterSymbol typeParameter &&
				SymbolEqualityComparer.Default.Equals(typeParameter.ContainingSymbol, hookMethod))
				return true;

			if (expectedValueType.IsVoid)
				return type.SpecialType == SpecialType.System_Void ||
					type.ToDisplayString(SymbolDisplayFormat.CSharpErrorMessageFormat) == "System.Void" ||
					type is INamedTypeSymbol namedType && IsAspectGeneratorType(namedType, "Void");

			return expectedValueType.Type is not null &&
				SymbolEqualityComparer.Default.Equals(type, expectedValueType.Type);
		}

		static bool IsAspectGeneratorType(INamedTypeSymbol type, string name)
		{
			if (type.Name != name)
				return false;

			var @namespace = type.ContainingNamespace.ToDisplayString();

			return @namespace is "" or "AspectGenerator";
		}

		internal static bool IsSupportedAsyncReturnTypeOf(IMethodSymbol method)
		{
			return IsSupportedAsyncReturnType(method.ReturnType, out _);
		}

		static bool IsSupportedAsyncReturnType(ITypeSymbol type, out ITypeSymbol? resultType)
		{
			resultType = null;

			if (type is not INamedTypeSymbol namedType ||
				namedType.Name is not ("Task" or "ValueTask") ||
				namedType.ContainingNamespace.ToDisplayString() != "System.Threading.Tasks")
				return false;

			if (namedType is { IsGenericType: true, TypeArguments: [var asyncResultType] })
				resultType = asyncResultType;

			return true;
		}

		static bool ImplementsType(ITypeSymbol type, string metadataName)
		{
			return IsType(type, metadataName) ||
				type.AllInterfaces.Any(i => IsType(i, metadataName));

			static bool IsType(ITypeSymbol type, string metadataName)
			{
				if (type is not INamedTypeSymbol namedType)
					return false;

				return namedType.ContainingNamespace.ToDisplayString() + "." + namedType.Name == metadataName;
			}
		}

		static void GenerateMethodBody(
			SourceProductionContext    spc,
			StringBuilder              sb,
			InvocationExpressionSyntax invocationExpression,
			IMethodSymbol              method,
			string                     interceptorName,
			string                     typeArguments,
			List<AttributeInfo>        attributes,
			int                        methodModifierPosition,
			Compilation                compilation)
		{
			var isReturnsAsyncType = IsSupportedAsyncReturnType(method.ReturnType, out var asyncResultType);
			var generateAsync      = GeneratesAsyncInterceptor(method, attributes);
			var generateArgs       = attributes.Any(d => GetAspectOptions(d).Any(a => a is { Key: "PassArguments", Value: true }));
			var targetMethodLocalGenerated = false;
			var returnsValue       = !(method.ReturnsVoid || generateAsync && asyncResultType is null);

			// A hook can skip the call or swallow its exception, so out parameters are assigned up front.
			//
			foreach (var p in method.Parameters)
				if (p.RefKind == RefKind.Out)
					sb.AppendLine($"\t\t\t{EscapeIdentifier(p.Name)} = default!;");

			if (method.Parameters.Any(static p => p.RefKind == RefKind.Out))
				sb.AppendLine();

			// Generate arguments.
			//
			if (generateArgs)
			{
				sb.Append("\t\t\tvar __args__ = new object?[] { ");

				if (method.IsStatic == false)
					sb.Append("__this__, ");

				foreach (var p in method.Parameters)
					sb.Append(EscapeIdentifier(p.Name)).Append(p.RefKind == RefKind.Out ? " = default, " : ", ");

				while (sb[^1] is ' ' or ',')
					sb.Length--;

				sb.Append(" };").AppendLine().AppendLine();
			}

			if (generateAsync)
				sb.Insert(methodModifierPosition, "async ");

			GenerateAttribute(0, "\t\t\t", false);

			void GenerateAttribute(int idx, string indent, bool isPrevData)
			{
				var attr = attributes[idx].AttributeClass!;

				// Get aspect attribute parameters.
				//
				object? onInit           = null;
				object? onUsing          = null; object? onUsingAsync      = null;
				object? onBeforeCall     = null; object? onBeforeCallAsync = null;
				object? onCall           = null;
				object? onAfterCall      = null; object? onAfterCallAsync  = null;
				object? onCatch          = null; object? onCatchAsync      = null;
				object? onFinally        = null; object? onFinallyAsync    = null;
				var     useInterceptType = false;
				var     passArguments    = false;
				var     useInterceptData = false;
				var     needInfo         = attributes.Count > 1 || generateAsync;

				foreach (var arg in GetAspectOptions(attributes[idx]))
					switch (arg.Key)
					{
						case "OnInit"            : onInit            = arg.Value; needInfo = true; break;
						case "OnUsing"           : onUsing           = arg.Value; needInfo = true; break;
						case "OnUsingAsync"      : onUsingAsync      = arg.Value; needInfo = true; break;
						case "OnBeforeCall"      : onBeforeCall      = arg.Value; needInfo = true; break;
						case "OnBeforeCallAsync" : onBeforeCallAsync = arg.Value; needInfo = true; break;
						case "OnCall"            : onCall            = arg.Value;                  break;
						case "OnAfterCall"       : onAfterCall       = arg.Value; needInfo = true; break;
						case "OnAfterCallAsync"  : onAfterCallAsync  = arg.Value; needInfo = true; break;
						case "OnCatch"           : onCatch           = arg.Value; needInfo = true; break;
						case "OnCatchAsync"      : onCatchAsync      = arg.Value; needInfo = true; break;
						case "OnFinally"         : onFinally         = arg.Value; needInfo = true; break;
						case "OnFinallyAsync"    : onFinallyAsync    = arg.Value; needInfo = true; break;
						case "UseInterceptType"  : useInterceptType  = arg.Value is true; break;
						case "PassArguments"     : passArguments     = arg.Value is true; break;
						case "UseInterceptData"  : useInterceptData  = arg.Value is true; break;
					}

				var returnType = generateAsync
					? asyncResultType is null ? "global::AspectGenerator.Void" : PrintType(asyncResultType)
					: method.ReturnsVoid ? "global::AspectGenerator.Void" : PrintType(method.ReturnType);

				// Generate AspectCallInfo.
				//
				if (needInfo)
				{
					sb
						.Append(indent).AppendLine($"// {SingleLine(((object?)attributes[idx].AppliedAttributeData ?? attributes[idx].AttributeClass).ToString())}")
						.Append(indent).AppendLine("//")
						;

					if (!targetMethodLocalGenerated)
					{
						sb
							.Append(indent)
							.AppendLine($"var __targetMethod__ = {interceptorName}_State{typeArguments}.TargetMethod;")
							.AppendLine()
							;
						targetMethodLocalGenerated = true;
					}

					sb
						.Append(indent).AppendLine($"var __aspect__{idx} = {(AspectLifetimeResolver.UsesInstanceLifetime(attributes[idx]) ? GetAppliedAspectConstruction(attributes[idx]) : $"{interceptorName}_State.Aspect{idx}")};")
						.Append(indent).AppendLine($"var __info__{idx}   = new global::AspectGenerator.Intercept{(useInterceptData ? "Data" : "Info")}<{returnType}>")
						.Append(indent).AppendLine("{")
						//.Append(indent).AppendLine($"\tReturnValue     = {(idx > 0 ? $"__info__{idx - 1}.ReturnValue" : $"default({(method.ReturnsVoid ? "Void" : $"{method.ReturnType}")})")},")
						.Append(indent).AppendLine($"\tMemberInfo = __targetMethod__,")
						.Append(indent).AppendLine($"\tAspect     = __aspect__{idx},")
						;

					if (passArguments)
						sb
							.Append(indent).AppendLine("\tMethodArguments = __args__,")
							;

					if (idx > 0 && !isPrevData)
						sb.Append(indent).AppendLine($"\tPreviousInfo = __info__{idx - 1}");

					sb
						.Append(indent).AppendLine("};")
						.AppendLine()
						;
				}

				// Generate OnInit.
				//
				if (onInit is not null)
				{
					GenerateInterceptType("", "OnInit")
						.Append(indent).AppendLine($"__info__{idx} = {PrintType(attr)}.{onInit}({PassHookArguments("OnInit", onInit)});")
						.AppendLine()
						;
				}

				// Generate OnUsing.
				//
				if (generateAsync && onUsingAsync is not null || onUsing is not null)
				{
					var isAsync = generateAsync && onUsingAsync != null;
					GenerateInterceptType("", "OnUsing")
						.Append(indent).AppendLine($"{(isAsync ? "await " : "")}using ({PrintType(attr)}.{(isAsync ? onUsingAsync : onUsing)}({(isAsync ? PassHookArguments("OnUsingAsync", onUsingAsync) : PassHookArguments("OnUsing", onUsing))}))")
						.Append(indent).AppendLine("{")
						;
					indent += '\t';
				}

				// If OnCatch or OnFinally is defined, generate try/catch/finally block.
				//
				if (generateAsync && onCatchAsync   is not null || onCatch   is not null ||
					generateAsync && onFinallyAsync is not null || onFinally is not null)
				{
					sb.Append(indent).AppendLine("try");
					sb.Append(indent).AppendLine("{");
					indent += '\t';
				}

				// Generate OnBeforeCall.
				//
				if (generateAsync && onBeforeCallAsync is not null || onBeforeCall is not null)
				{
					GenerateInterceptType("", "OnBeforeCall");
					GenerateMethodCall("OnBeforeCall", onBeforeCallAsync, onBeforeCall)
						.AppendLine()
						.Append(indent).AppendLine($"if (__info__{idx}.InterceptResult != global::AspectGenerator.InterceptResult.Return)")
						.Append(indent).AppendLine("{")
						;

					indent += '\t';
				}

				// Generate next attribute...
				//
				if (idx < attributes.Count - 1)
				{
					sb.Append(indent).AppendLine("{");

					GenerateAttribute(idx + 1, indent + '\t', useInterceptData);

					TrimEnd(sb);

					sb
						.Append(indent).AppendLine("}")
						.AppendLine()
						;
				}
				// .. or call the target method.
				//
				else
				{
					sb
						.Append(indent)
						.Append(
							!returnsValue
								? generateAsync ? "await " : string.Empty
								: $"{(needInfo ? $"__info__{idx}.ReturnValue" : "var __return__")} = {(generateAsync ? "await " : "")}")
						.Append(
							onCall is null
								? method.IsStatic || method.MethodKind == MethodKind.ReducedExtension
									? PrintType(method.ContainingType)
									: "__this__"
								: PrintType(attr))
						.Append('.')
						.Append(onCall is null ? PrintMethodName(method) : onCall)
						.Append('(')
						;

					if (method.MethodKind == MethodKind.ReducedExtension || onCall is not null && method.IsStatic is false)
					{
						if (onCall is null && method.MethodKind == MethodKind.ReducedExtension)
							sb.Append(method.ReducedFrom!.Parameters[0].RefKind switch
							{
								RefKind.Ref                                  => "ref ",
								RefKind.In or RefKind.RefReadOnlyParameter   => "in ",
								_                                            => ""
							});

						sb.Append("__this__");

						if (method.Parameters.Length > 0)
							sb.Append(", ");
					}

					foreach (var p in method.Parameters)
					{
						sb
							.Append(
								p.RefKind switch
								{
									RefKind.Ref => "ref ",
									RefKind.Out => "out ",
									RefKind.In  => "in ",
									_           => ""
								})
							// A dynamic argument would bind the call at run time, possibly to another overload.
							.Append(p.Type.TypeKind == TypeKind.Dynamic && p.RefKind == RefKind.None ? "(object?)" : "")
							.Append(EscapeIdentifier(p.Name))
							.Append(", ");
					}

					if (method.Parameters.Length > 0)
						sb.Length -= 2;

					sb
						.AppendLine(");")
						.AppendLine()
						;
				}

				// Generate OnAfterCall.
				//
				if (generateAsync && onAfterCallAsync is not null || onAfterCall is not null)
				{
					GenerateInterceptType("", "OnAfterCall");
					GenerateMethodCall("OnAfterCall", onAfterCallAsync, onAfterCall)
						.AppendLine();
				}

				// Generate OnBeforeCall end.
				//
				if (generateAsync && onBeforeCallAsync is not null || onBeforeCall is not null)
				{
					TrimEnd(sb);

					indent = indent[..^1];

					sb
						.Append(indent)
						.AppendLine("}")
						.AppendLine()
						;
				}

				// If OnCatch or OnFinally is defined, generate try/catch/finally block end.
				//
				if (generateAsync && onCatchAsync   is not null || onCatch   is not null ||
					generateAsync && onFinallyAsync is not null || onFinally is not null)
				{
					indent = indent[..^1];

					TrimEnd(sb);

					sb.AppendLine($"{indent}}}");

					// Generate OnCatch.
					//
					sb
						.Append(indent).AppendLine("catch (global::System.Exception __ex__)")
						.Append(indent).AppendLine("{")
						.Append(indent).AppendLine($"\t__info__{idx}.Exception{(onCatch is null ? null : "      ")} = __ex__;")
						;

					if (generateAsync && onCatchAsync is not null || onCatch is not null)
					{
						sb.Append(indent).AppendLine($"\t__info__{idx}.InterceptResult = global::AspectGenerator.InterceptResult.ReThrow;");

						GenerateInterceptType("\t", "OnCatch")
							.AppendLine()
							.Append('\t')
							;

						GenerateMethodCall("OnCatch", onCatchAsync, onCatch)
							.AppendLine()
							.Append(indent).AppendLine($"\tif (__info__{idx}.InterceptResult == global::AspectGenerator.InterceptResult.ReThrow)")
							.Append(indent).AppendLine("\t\tthrow;")
							;
					}
					else
					{
						sb.Append(indent).AppendLine("\tthrow;");
					}

					sb.Append(indent).AppendLine("}");

					// Generate OnFinally.
					//
					if (generateAsync && onFinallyAsync is not null || onFinally is not null)
					{
						sb
							.Append(indent).AppendLine("finally")
							.Append(indent).AppendLine("{");

						GenerateInterceptType("\t", "OnFinally")
							.Append('\t')
							;

						GenerateMethodCall("OnFinally", onFinallyAsync, onFinally)
							.Append(indent).AppendLine("}")
							;
					}

					sb.AppendLine();
				}

				// Generate OnUsing.
				//
				if (generateAsync && onUsingAsync is not null || onUsing is not null)
				{
					indent = indent[..^1];

					TrimEnd(sb);

					sb
						.Append(indent)
						.AppendLine("}")
						.AppendLine()
						;
				}

				// Generate return.
				//
				if (idx > 0)
					sb.Append(indent).AppendLine($"__info__{idx - 1}.ReturnValue = __info__{idx}.ReturnValue;");
				else if (returnsValue)
					sb.AppendLine($"\t\t\treturn {(needInfo ? $"__info__{idx}.ReturnValue" : "__return__")};");

				TrimEnd(sb);

				string PassInfo(int idx)
				{
					return $"{(useInterceptData ? "ref " : "")}__info__{idx}";
				}

				StringBuilder GenerateMethodCall(string option, object? onAsync, object? call)
				{
					if (generateAsync && onAsync is not null)
						return sb.Append(indent).AppendLine($"await {PrintType(attr)}.{onAsync}({PassHookArguments(option + "Async", onAsync)});");
					return sb.Append(indent).AppendLine($"{PrintType(attr)}.{call}({PassHookArguments(option, call)});");
				}

				// The arguments follow the overload the hook validation and the AG0003 check resolved, not a lookup of
				// their own: a private overload that takes the aspect must not decide the call of a public one.
				string PassHookArguments(string option, object? hookName)
				{
					return hookName is string name &&
						ResolveLifecycleHook(InterceptorShape.GetAspectTypeAsWritten(attr, compilation), option, name, method, useInterceptData, compilation) is { Parameters.Length: 2 }
						? $"__aspect__{idx}, {PassInfo(idx)}"
						: PassInfo(idx);
				}

				StringBuilder GenerateInterceptType(string additionalIndent, string interceptType)
				{
					if (useInterceptType)
					{
						sb
							.Append(additionalIndent)
							.Append(indent)
							.AppendLine($"__info__{idx}.InterceptType = global::AspectGenerator.InterceptType.{interceptType};");
					}

					return sb;
				}
			}
		}

		static void TrimEnd(StringBuilder sb)
		{
			while (sb[^1] is '\r' or '\n')
				sb.Length--;

			sb.AppendLine();
		}

		static string PrintValue(object? val, ITypeSymbol? type)
		{
			if (val is null)
				return "null";

			if (type?.TypeKind == TypeKind.Enum)
				return PrintCast(type, PrintValue(val, null));

			return val switch
			{
				string           s => SymbolDisplay.FormatLiteral(s, quote: true),
				char             c => SymbolDisplay.FormatLiteral(c, quote: true),
				bool             b => b ? "true" : "false",
				byte             b => b.ToString(CultureInfo.InvariantCulture),
				sbyte            b => b.ToString(CultureInfo.InvariantCulture),
				short            n => n.ToString(CultureInfo.InvariantCulture),
				ushort           n => n.ToString(CultureInfo.InvariantCulture),
				int              n => n.ToString(CultureInfo.InvariantCulture),
				uint             n => n.ToString(CultureInfo.InvariantCulture) + "u",
				long             n => n.ToString(CultureInfo.InvariantCulture) + "L",
				ulong            n => n.ToString(CultureInfo.InvariantCulture) + "uL",
				float            f => PrintSingle(f),
				double           d => PrintDouble(d),
				decimal          d => d.ToString(CultureInfo.InvariantCulture) + "m",
				ITypeSymbol      t => $"typeof({t.ToDisplayString(SymbolDisplayFormat.FullyQualifiedFormat)})",
				_                  => Convert.ToString(val, CultureInfo.InvariantCulture) ?? "null"
			};

			static string PrintSingle(float value)
			{
				if (float.IsNaN(value))
					return "float.NaN";
				if (float.IsPositiveInfinity(value))
					return "float.PositiveInfinity";
				if (float.IsNegativeInfinity(value))
					return "float.NegativeInfinity";

				return value.ToString("R", CultureInfo.InvariantCulture) + "f";
			}

			static string PrintDouble(double value)
			{
				if (double.IsNaN(value))
					return "double.NaN";
				if (double.IsPositiveInfinity(value))
					return "double.PositiveInfinity";
				if (double.IsNegativeInfinity(value))
					return "double.NegativeInfinity";

				return value.ToString("R", CultureInfo.InvariantCulture) + "d";
			}
		}

		/// <summary>
		/// Type names in generated code are fully qualified with <c>global::</c>, so they bind the same way whatever
		/// namespace the interceptors are emitted into and whatever the user's code declares there.
		/// Nullable reference annotations are kept: the generated file is compiled with <c>#nullable enable</c>.
		/// </summary>
		static readonly SymbolDisplayFormat _typeFormat = SymbolDisplayFormat.FullyQualifiedFormat
			.AddMiscellaneousOptions(SymbolDisplayMiscellaneousOptions.IncludeNullableReferenceTypeModifier);

		// Default values are left out: every call site passes all arguments to the interceptor, and a default value
		// printed by the symbol display (an enum member or double.NaN without its type, a decimal literal) does not compile.
		static readonly SymbolDisplayFormat _parameterFormat = _typeFormat
			.WithParameterOptions(
				SymbolDisplayParameterOptions.IncludeParamsRefOut |
				SymbolDisplayParameterOptions.IncludeType         |
				SymbolDisplayParameterOptions.IncludeName);

		static string PrintType(ITypeSymbol type)
		{
			return type.ToDisplayString(_typeFormat);
		}

		static string PrintMethodName(IMethodSymbol method)
		{
			var name = EscapeIdentifier(method.Name);

			// The call in the interceptor repeats the call site's type arguments; they cannot always be inferred again.
			var callTarget = method.GetConstructedReducedFrom() ?? method;

			if (!callTarget.IsGenericMethod)
				return name;

			return $"{name}<{string.Join(", ", callTarget.TypeArguments.Select(PrintType))}>";
		}

		static string EscapeIdentifier(string name)
		{
			return SyntaxFacts.IsReservedKeyword(SyntaxFacts.GetKeywordKind(name)) ? "@" + name : name;
		}

		static string PrintParameters(IMethodSymbol method)
		{
			var parameters = method.Parameters;
			var sb         = new StringBuilder();

			if (method.IsStatic == false)
				sb.Append($"this {GetReceiverRefKind(method)}{PrintType(method.ReceiverType!)} __this__, ");

			foreach (var p in parameters)
				sb
					.Append(PrintParameter(p))
					.Append(", ")
					;

			if (parameters.Length != 0 || method.IsStatic == false)
				sb.Length -= 2;

			return sb.ToString();
		}

		/// <summary>
		/// The interceptor of a struct instance method takes the receiver by reference, as the target's <c>this</c> is;
		/// a reduced extension method passes on the ref kind of its <c>this</c> parameter.
		/// </summary>
		static string GetReceiverRefKind(IMethodSymbol method)
		{
			if (method.MethodKind == MethodKind.ReducedExtension)
			{
				return method.ReducedFrom!.Parameters[0].RefKind switch
				{
					RefKind.Ref                  => "ref ",
					RefKind.In                   => "in ",
					RefKind.RefReadOnlyParameter => "ref readonly ",
					_                            => ""
				};
			}

			if (method.ReceiverType is not { IsValueType: true } receiver || receiver.TypeKind == TypeKind.TypeParameter)
				return "";

			return method.IsReadOnly || receiver.IsReadOnly ? "in " : "ref ";
		}

		static string PrintParameter(IParameterSymbol parameter)
		{
			return parameter.ToDisplayString(_parameterFormat);
		}

		/// <summary>
		/// Text inserted into a generated comment: a line break in it would end the comment and turn the rest into code.
		/// </summary>
		static string SingleLine(string text)
		{
			var sb      = new StringBuilder(text.Length);
			var inSpace = false;

			foreach (var c in text)
			{
				if (char.IsWhiteSpace(c) || char.IsControl(c))
				{
					if (!inSpace)
						sb.Append(' ');
					inSpace = true;
				}
				else
				{
					sb.Append(c);
					inSpace = false;
				}
			}

			return sb.ToString().Trim();
		}

		/// <summary>
		/// The method info of a target whose ref struct or pointer parameters cannot appear in an expression tree. A static or
		/// extension method is taken from a delegate created over its method group; an instance method (never generic
		/// here, see <see cref="InterceptorShape.GetUnsupportedReason"/>) is looked up by its parameter types.
		/// </summary>
		static (string Expression, string? DelegateDeclaration) GetTargetMethodByReflection(IMethodSymbol method)
		{
			var definition = method.MethodKind == MethodKind.ReducedExtension
				? method.GetConstructedReducedFrom()!
				: method;

			if (definition.IsStatic)
			{
				var parameters = string.Join(", ", definition.Parameters.Select(PrintParameter));
				var returnType = definition.ReturnsVoid ? "void" : PrintType(definition.ReturnType);

				return ($"new TargetDelegate({PrintType(definition.ContainingType)}.{PrintMethodName(definition)}).Method", $"delegate {returnType} TargetDelegate({parameters});");
			}

			var types = string.Join(", ", definition.Parameters.Select(static p =>
			{
				// typeof takes no nullable reference annotations.
				var type = p.Type.TypeKind == TypeKind.Dynamic ? "typeof(object)" : $"typeof({p.Type.ToDisplayString(SymbolDisplayFormat.FullyQualifiedFormat)})";

				return p.RefKind == RefKind.None ? type : $"{type}.MakeByRefType()";
			}));

			return ($"typeof({PrintType(definition.ContainingType)}).GetMethod(\"{definition.Name}\", global::System.Reflection.BindingFlags.Public | global::System.Reflection.BindingFlags.NonPublic | global::System.Reflection.BindingFlags.Instance | global::System.Reflection.BindingFlags.DeclaredOnly, null, new global::System.Type[] {{ {types} }}, null)!", null);
		}

		static string GetMethodOf(IMethodSymbol method, string interceptorName)
		{
			var sb = new StringBuilder();

			sb.Append("(() => ");

			sb
				.Append(method.IsStatic || method.MethodKind == MethodKind.ReducedExtension ? PrintType(method.ContainingType) : $"default({PrintType(method.ReceiverType!)})")
				.Append('.')
				.Append(PrintMethodName(method))
				.Append('(')
				;

			if (method.MethodKind == MethodKind.ReducedExtension)
				sb.Append($"default({PrintType(method.ReceiverType!)}), ");

			foreach (var p in method.Parameters)
				switch (p.RefKind)
				{
					case RefKind.Ref : sb.Append($"ref {interceptorName}_Arg_{p.Name}, "); break;
					case RefKind.In  : sb.Append($"in {interceptorName}_Arg_{p.Name}, ");  break;
					case RefKind.Out : sb.Append($"out {interceptorName}_Arg_{p.Name}, "); break;
					// A dynamic argument would make the call in the expression tree a dynamic operation.
					default          : sb.Append($"default({(p.Type.TypeKind == TypeKind.Dynamic ? "object" : PrintType(p.Type))}), "); break;
				}

			while (sb[^1] is ',' or ' ')
				sb.Length--;

			sb.Append("))");

			return sb.ToString();
		}
	}
}
